-- Walkthrough steps 2 to 4 rewrite (VIB-160).
--
-- Same treatment as step 1 in 20260916130000: plainer copy and a choice of
-- prompts. Stack and Deploy had no prompt, so each gains a "Stuck?" prompt,
-- which also gives them the open-in-AI-tool links. `prompt` stays set to the
-- first version for builds that predate `prompts`.
--
-- Content only. Task ids are unchanged, so nobody's saved ticks move.
update wizards
set steps = jsonb_set(jsonb_set(jsonb_set(steps, '{1}', '{"key": "stack", "title": "Stack", "intro": "Choose tools that stay out of your way. Nothing here is forever.", "blocks": [{"kind": "text", "body": "For a first project, the tools matter much less than picking some and moving on. Use Next.js to build the site, Tailwind to style it, and Vercel to put it online. Skip the database unless your idea really needs to save something. A list of recipes can live in a file just fine."}, {"kind": "code", "language": "bash", "code": "npx create-next-app@latest my-project", "expected": "A few questions, then a new my-project folder. Say yes to TypeScript, yes to Tailwind and yes to App Router. For everything else, the default is fine."}, {"kind": "code", "language": "bash", "code": "cd my-project\nnpm run dev", "expected": "A line saying Local: http://localhost:3000. Open that address in your browser and you should see the Next.js starter page."}, {"kind": "callout", "tone": "tip", "body": "See the starter page? Then the fiddly part of setup is done. From here on it is: edit a file, save, look at the browser. Repeat until it is yours."}, {"kind": "prompt", "label": "Stuck? Pick a prompt and ask your AI tool", "prompt": "I am setting up my first Next.js project and something went wrong.\n\nThe command I ran: [paste the command]\nWhat I saw: [paste the full error message]\nMy computer: [Windows, Mac or Linux]\n\nExplain in plain words what the error means, then give me the exact steps to fix it, one at a time. Assume I am a beginner.", "prompts": [{"title": "Fix an error", "prompt": "I am setting up my first Next.js project and something went wrong.\n\nThe command I ran: [paste the command]\nWhat I saw: [paste the full error message]\nMy computer: [Windows, Mac or Linux]\n\nExplain in plain words what the error means, then give me the exact steps to fix it, one at a time. Assume I am a beginner."}, {"title": "Explain the files", "prompt": "I just created a Next.js project with create-next-app. I am a beginner.\n\nExplain, in plain words:\n1. Which files and folders I actually need to care about right now\n2. Which ones I can safely ignore for my first project\n3. Which file to edit to change the text on the home page\n\nKeep it short. I do not need the history of JavaScript."}, {"title": "Build my first screen", "prompt": "I have a fresh Next.js project with Tailwind. My project idea is: [your one-sentence idea].\n\nWrite the code for app/page.tsx so it shows a simple first version of that one screen.\n- Use made-up example data, no database\n- Keep it all in one file\n- Add short comments so I can follow what each part does\n\nThen tell me how to check it works at localhost:3000."}]}, {"kind": "checklist", "tasks": [{"id": "stack-created", "label": "Created the project with create-next-app"}, {"id": "stack-running", "label": "Saw the starter page at localhost:3000"}, {"id": "stack-edited", "label": "Changed some text in app/page.tsx and watched it update by itself"}]}]}'::jsonb), '{2}', '{"key": "deploy", "title": "Deploy", "intro": "Put it online today, while there is nothing to break. Do not leave it for the end.", "blocks": [{"kind": "text", "body": "Going live early turns every change after this into a small, safe step, instead of one big scary leap at the finish. You also get a real link to send people the moment it is worth showing off."}, {"kind": "code", "language": "bash", "code": "git init\ngit add -A\ngit commit -m \"first commit\"", "expected": "A list of create mode lines, one per file, then a commit ID. If git asks who you are, set your name and email with git config, then run the commit again."}, {"kind": "text", "body": "Next, create an empty repository on GitHub. Right after you create it, GitHub shows the exact two commands to connect it and push your code. Copy them, run them, done."}, {"kind": "text", "body": "Once your code is on GitHub, go to vercel.com and choose Add New Project. Pick your repository, keep every default setting and press Deploy. A minute or two later you have a live link. Yes, on the actual internet."}, {"kind": "callout", "tone": "tip", "body": "From now on, every push to your main branch goes live by itself. There is no separate deploy step to remember, which is good, because you would forget it."}, {"kind": "prompt", "label": "Stuck? Pick a prompt and ask your AI tool", "prompt": "I am trying to put my first project on GitHub and got stuck.\n\nWhat I ran: [paste the commands]\nWhat I saw: [paste the full message]\n\nExplain what went wrong in plain words and give me the exact commands to fix it, one step at a time. I am a beginner, so do not skip steps.", "prompts": [{"title": "Fix a GitHub error", "prompt": "I am trying to put my first project on GitHub and got stuck.\n\nWhat I ran: [paste the commands]\nWhat I saw: [paste the full message]\n\nExplain what went wrong in plain words and give me the exact commands to fix it, one step at a time. I am a beginner, so do not skip steps."}, {"title": "Fix a failed deploy", "prompt": "My Vercel deploy failed. This is my first time deploying anything.\n\nHere is the build log: [paste the red part of the log]\n\nTell me:\n1. What actually broke, in one or two plain sentences\n2. Which file to change, and what to change it to\n3. How to check the fix works on my computer before I push again"}, {"title": "Explain what just happened", "prompt": "I just pushed my project to GitHub and Vercel put it online. It works, but I am not sure how.\n\nExplain in plain words, as if to a friend:\n1. What git, GitHub and Vercel each did\n2. What happens now when I change a file and push again\n3. One mistake beginners often make with this setup, and how to avoid it"}]}, {"kind": "checklist", "tasks": [{"id": "deploy-git", "label": "Made my first commit"}, {"id": "deploy-github", "label": "Pushed the code to GitHub"}, {"id": "deploy-vercel", "label": "Deployed on Vercel and opened the live link"}, {"id": "deploy-second", "label": "Pushed a second change and watched it go live by itself"}]}]}'::jsonb), '{3}', '{"key": "launch", "title": "Launch", "intro": "The last mile: make it yours, then show one person.", "blocks": [{"kind": "text", "body": "Nothing in this step is hard. It is just the part everyone skips, and it is the difference between a folder on your laptop and something that really exists."}, {"kind": "prompt", "label": "Pick a prompt and get a review before you share", "prompt": "Here is my first web project: [paste your link].\n\nLook at it the way a stranger would and tell me:\n1. Within five seconds, is it obvious what this does?\n2. Is anything visibly broken or half-finished?\n3. What is the one fix worth doing in under thirty minutes?\n\nDo not suggest new features. I am trying to finish, not start again.", "prompts": [{"title": "Review it like a stranger", "prompt": "Here is my first web project: [paste your link].\n\nLook at it the way a stranger would and tell me:\n1. Within five seconds, is it obvious what this does?\n2. Is anything visibly broken or half-finished?\n3. What is the one fix worth doing in under thirty minutes?\n\nDo not suggest new features. I am trying to finish, not start again."}, {"title": "Pre-launch checklist", "prompt": "I am about to share my first web project: [paste your link]. It is built with Next.js and hosted on Vercel.\n\nGive me a short pre-launch checklist, ten items at most, covering:\n- the page title and the preview that shows when someone shares the link\n- how it looks on a phone\n- leftover starter text or placeholder content\n\nFor each item, tell me exactly where to look and how to fix it."}, {"title": "Write my share message", "prompt": "I just finished my first web project: [paste your link]. It does this: [your one-sentence idea].\n\nWrite three short messages I could use to share it:\n1. One for a friend on WhatsApp\n2. One for LinkedIn or X\n3. One asking someone for honest feedback\n\nKeep them short and friendly. No hype, and no rocket emojis."}]}, {"kind": "checklist", "tasks": [{"id": "launch-title", "label": "Set the page title and description, so it no longer says Create Next App"}, {"id": "launch-mobile", "label": "Opened it on a phone and fixed anything clearly broken"}, {"id": "launch-placeholder", "label": "Removed all the leftover starter content"}, {"id": "launch-share", "label": "Sent the link to one real human being"}]}, {"kind": "callout", "tone": "info", "body": "That last task is the one that counts. A project nobody has seen is still a draft. Once one person has opened it, you have shipped, and the next project gets a lot easier."}]}'::jsonb)
where slug = 'ship-your-first-web-project'
  and steps->1->>'key' = 'stack'
  and steps->2->>'key' = 'deploy'
  and steps->3->>'key' = 'launch';
